(() => {
'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format((Number(n)||0)/100);
const date=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):'À préciser';
const dt=n=>new Date(n).toLocaleString('fr-FR',{timeZone:'Europe/Paris',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Paris'}).format(new Date());
const safeLink=s=>{try{const u=new URL(s);return u.protocol==='https:'&&['eywacoffeecatering.com','eywa-booking.eywa-booking-cloudflare.workers.dev','www.google.com','search.google.com','g.page','maps.app.goo.gl'].includes(u.hostname)?esc(u.href):'#';}catch{return '#';}};
const titles={home:'Vue d’ensemble',calendar:'Calendrier',dossiers:'Dossiers clients',tasks:'Préparation',staff:'Baristas',equipment:'Matériel',suppliers:'Fournisseurs',prospects:'Prospection',settings:'Réglages'};
let state=null,csrf='',view='home',challenge='',search='',filter='all',taskFilter='all',month=new Date().getMonth(),year=new Date().getFullYear(),opened=null,showTests=false;
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function loginView(){state=null;csrf='';$('#content').replaceChildren();$('#detail').close();$('#app').hidden=true;$('#login').hidden=false;}
async function api(path,body){const res=await fetch('/espace/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-EYWA-CSRF':csrf}:{},body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok){if(res.status===401&&!['verify','login','passkey-login','passkey-login-options'].includes(path))loginView();throw Error(data.error||'Réessayez.');}return data;}
async function load(){state=await api('overview');$('#login').hidden=true;$('#app').hidden=false;$('#today').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Paris'}).toUpperCase();render();}
async function act(body,reopen){await api('action',body);await load();if(reopen)await openEvent(reopen);toast('C’est enregistré.');}
const isTest=q=>/(?:test|essai|démonstration|demonstration|technique)/i.test((q.name||'')+' '+(q.eventType||''))||['contact.eywa08@gmail.com','louis.lepoulain08@gmail.com'].includes(String(q.email||'').toLowerCase());
const events=()=>[...state.events,...(state.externalEvents||[])].filter(e=>e.status!=='cancelled'&&(showTests||!isTest(e.data)));
const quotes=()=>state.quotes.filter(q=>showTests||!isTest(q));
const badge=s=>'<span class="badge '+esc(s)+'">'+({open:'Devis envoyé',paid:'Réservé',closed:'Relances arrêtées',confirmed:'Réservé',completed:'Terminé',cancelled:'Annulé',calendar:'Google Agenda'}[s]||esc(s))+'</span>';
const stages={new:'À contacter',contacted:'Contact pris',waiting:'En attente du client',lost:'Sans suite'};
const empty=s=>'<p class="empty">'+esc(s)+'</p>';
const panel=(title,body)=>'<section class="panel"><h2>'+esc(title)+'</h2>'+body+'</section>';
const field=(name,label,value='',type='text',extra='')=>'<div class="field"><label for="f-'+name+'">'+label+'</label><input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>';
const inputSelect=(name,label,options,value)=>'<div class="field"><label for="f-'+name+'">'+label+'</label><select id="f-'+name+'" name="'+name+'">'+options.map(([v,t])=>'<option value="'+esc(v)+'"'+(String(v)===String(value)?' selected':'')+'>'+esc(t)+'</option>').join('')+'</select></div>';
function row(e){const q=e.data,d=new Date(q.date+'T12:00:00Z');return '<button class="event-row" data-event="'+esc(e.id)+'"><span class="date-tile"><b>'+d.getDate()+'</b><small>'+d.toLocaleDateString('fr-FR',{month:'short'})+'</small></span><span class="row-info"><b>'+esc(q.name)+'</b><small>'+esc(q.eventType)+' · '+esc(q.time)+(e.calendarOnly?'':' · '+esc(q.guests)+' invités')+'</small><small>'+esc(q.location)+'</small></span>'+badge(e.status)+'</button>';}
function taskRow(t){const e=state.events.find(e=>e.id===t.event_id);return '<label class="task '+(t.done?'done':'')+'"><input type="checkbox" data-task="'+esc(t.id)+'" '+(t.done?'checked':'')+'><span><span class="task-name">'+esc(t.title)+'</span><small class="'+(!t.done&&t.due_date<today()?'overdue':'')+'">'+esc(e?.data.name||'Événement')+' · '+date(t.due_date)+'</small>'+(t.done?'<small class="completed-note">Terminée '+(t.completed_at?dt(t.completed_at):'')+'</small>':'')+'</span></label>';}
function home(){const upcoming=events().filter(e=>e.ends_at>Date.now()).sort((a,b)=>a.starts_at-b.starts_at),tasks=state.tasks.filter(t=>!t.done&&t.due_date<=today()&&events().some(e=>e.id===t.event_id));return '<section class="hero-note"><div><h2>Bonjour Louis.</h2><p>'+(!upcoming.length?'Votre prochain bel événement commence ici. Tout est prêt pour accueillir les nouvelles réservations.':'Vos prochains événements et les petites choses à préparer, en un coup d’œil.')+'</p></div><span class="leaf" aria-hidden="true">❦</span></section><div class="stats"><button class="stat" data-view="calendar"><span>ÉVÉNEMENTS À VENIR</span><strong>'+upcoming.length+'</strong></button><button class="stat" data-view="dossiers" data-filter="open"><span>DEVIS À SUIVRE</span><strong>'+quotes().filter(q=>q.state==='open').length+'</strong></button><button class="stat" data-view="tasks"><span>TÂCHES À TRAITER</span><strong>'+tasks.length+'</strong></button></div>'+panel('Devis à suivre',quotes().filter(q=>q.state==='open').map(quoteRow).join('')||empty('Aucun devis à suivre.'))+'<div class="panel"><span class="muted">Soldes restant à encaisser</span><h2>'+euro((state.finances||[]).filter(f=>!f.settled&&(showTests||!isTest(f))).reduce((n,f)=>n+(Number(f.balance_cents)||0),0))+'</h2><small>Selon les factures émises et les paiements confirmés.</small></div><div class="columns">'+panel('Les prochains rendez-vous',upcoming.slice(0,5).map(row).join('')||empty('Aucun événement à venir.'))+panel('À préparer',tasks.slice(0,8).map(taskRow).join('')||empty('Tout est à jour.'))+'</div>'+(state.errors.length?panel('À vérifier',state.errors.map(e=>'<p><span class="badge danger">Envoi à réessayer</span> '+esc(e.kind||'Message')+' · '+e.attempts+' tentative(s). Le système réessaie automatiquement.</p>').join('')):'');}
function quoteRow(q){return '<button class="event-row quote-row" data-event="quote-'+esc(q.id)+'"><span class="row-info"><b>'+esc(q.name)+'</b><small>'+esc(q.eventType)+' · '+date(q.date)+' · '+euro(q.totalCents)+'</small><small>'+esc(stages[q.stage]||stages.new)+(q.nextActionDate?' · À recontacter le '+date(q.nextActionDate):'')+'</small></span><span class="open-quote">Ouvrir le dossier →</span></button>';}
function correspondencePanel(e){const c=e.correspondence;if(!c)return '';const t=c.tracking,d=c.drafts.find(d=>d.status==='draft'),q=e.originalQuote||e.data;return '<hr class="split-line"><h2>Suivre ce devis</h2><form id="quote-tracking-form" data-quote="'+esc(e.quote_id)+'" data-version="'+t.version+'">'+inputSelect('stage','Suivi commercial',Object.entries(stages),t.stage)+field('nextActionDate','Prochain contact prévu',t.next_action_date||'','date')+'<div class="field"><label for="quote-notes">Notes internes</label><textarea id="quote-notes" name="notes" maxlength="6000" placeholder="Ce que vous avez convenu, ce qu’il reste à préciser…">'+esc(t.notes)+'</textarea></div><p class="subtle">« Sans suite » arrête aussi les relances. Ces notes restent privées.</p><button>Enregistrer le suivi</button></form><h3>Relances automatiques</h3><p class="muted">'+(c.quoteState==='paid'?'Arrêtées : la réservation est réglée.':c.quoteState==='closed'?'Arrêtées pour ce devis.':'Elles s’arrêtent dès le paiement ou sur demande du client.')+'</p><ul class="reminder-list">'+c.reminders.filter(r=>[1,3,5].includes(r.day)).map(r=>'<li><b>J+'+r.day+'</b><span>'+dt(r.due_at)+'</span><span class="badge">'+esc(r.delivery_status==='sent'?'Envoyée le '+dt(r.sent_at):r.delivery_status==='pending'&&r.last_error?'Envoi à réessayer':r.delivery_status==='sending'?'En cours':c.quoteState!=='open'||r.state==='cancelled'?'Arrêtée':r.state==='skipped'?'Non envoyée':r.state==='queued'?'En attente d’envoi':'Programmée')+'</span></li>').join('')+'</ul>'+(!c.reminders.length?empty('Aucune relance programmée pour ce devis.'):'')+'<hr class="split-line"><h2>Un mail personnalisé</h2><p class="muted">Dictez-moi vos idées dans notre conversation, puis collez ici le texte préparé. La présentation beige EYWA et la signature sont ajoutées automatiquement.</p><p><small>Destinataire</small><br><b>'+esc(q.name)+' · '+esc(q.email)+'</b></p><form id="mail-draft-form" data-quote="'+esc(e.quote_id)+'" data-id="'+esc(d?.id||'')+'" data-version="'+(d?.version||0)+'">'+field('subject','Objet',d?.subject||'Votre événement avec EYWA','text','required maxlength="200"')+'<div class="field"><label for="personal-body">Votre message</label><textarea id="personal-body" name="body" rows="10" maxlength="6000" placeholder="Bonjour…">'+esc(d?.body_text||'')+'</textarea></div><div class="inline-actions"><button>Enregistrer le brouillon</button>'+(d?'<a class="button secondary" href="/espace/api/draft-preview?id='+encodeURIComponent(d.id)+'" target="_blank" rel="noopener">Voir l’aperçu du mail</a><button type="button" data-send-draft="'+esc(d.id)+'" data-version="'+d.version+'" data-recipient="'+esc(q.email)+'" '+(!d.body_text.trim()?'disabled':'')+'>Envoyer au client</button>':'')+'</div><p class="subtle">Enregistrez puis vérifiez l’aperçu avant l’envoi. Aucune remise ni modification du devis n’est appliquée par ce message.</p></form>'+(c.drafts.some(x=>x.status==='queued')?'<h3>Vos messages personnalisés</h3>'+c.drafts.filter(x=>x.status==='queued').map(d=>'<p>'+esc(d.subject)+' · <b>'+esc(d.delivery_status==='sent'?'Envoyé le '+dt(d.sent_at):d.delivery_status==='sending'?'En cours':'En attente d’envoi')+'</b></p>').join(''):'');}
function calendarConnection(){const c=state.calendar||{},stale=c.enabled&&(!c.last_success||Date.now()-c.last_success>6*3600000);return '<section class="panel calendar-connection"><div><h2>Mon Google Agenda</h2><p>'+(!c.configured?'Connexion automatique à finaliser.':c.last_error?'Actualisation à vérifier. Les derniers créneaux restent conservés.':c.last_success?'Dernière synchronisation : '+dt(c.last_success):'Première synchronisation en attente.')+'</p><small>'+(c.mode==='busy'?'Créneaux occupés de votre agenda personnel.':'Seuls les événements portant « EYWA » dans leur titre sont repris.')+' Lecture seule · actualisation toutes les 15 minutes · disponibilités bloquées à la journée.</small>'+(stale?'<p class="danger-text">Synchronisation trop ancienne : les nouvelles réservations sont suspendues jusqu’à l’actualisation.</p>':'')+'</div>'+(c.configured?'<button class="secondary" data-command="calendar-refresh">Actualiser l’agenda</button>':'')+'</section>';}
function calendar(){const first=new Date(year,month,1),offset=(first.getDay()+6)%7,count=new Date(year,month+1,0).getDate();let cells=Array.from({length:offset},()=>'<div class="calendar-day blank"></div>').join('');for(let d=1;d<=count;d++){const ds=year+'-'+String(month+1).padStart(2,'0')+'-'+String(d).padStart(2,'0'),list=events().filter(e=>e.data.date<=ds&&new Date(e.ends_at-1).toLocaleDateString('sv-SE',{timeZone:'Europe/Paris'})>=ds),blocks=state.blocks.filter(b=>!b.event_id&&b.from_date<=ds&&b.to_date>=ds);cells+='<div class="calendar-day '+(ds===today()?'today':'')+'"><b>'+d+'</b>'+list.map(e=>'<button class="calendar-event" data-event="'+esc(e.id)+'">'+esc(e.data.time)+' · '+esc(e.data.name)+'</button>').join('')+blocks.map(b=>'<div class="calendar-block">'+esc(b.label)+'</div>').join('')+'</div>';}
return calendarConnection()+'<div class="section-head"><h2>'+first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})+'</h2><div class="month-controls"><button class="secondary" data-month="-1" aria-label="Mois précédent">←</button><button class="secondary" data-month="0">Aujourd’hui</button><button class="secondary" data-month="1" aria-label="Mois suivant">→</button><button data-command="block">Bloquer des dates</button></div></div><div class="calendar">'+['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(d=>'<div class="weekday">'+d+'</div>').join('')+cells+'</div><p class="subtle">Les réservations du site bloquent actuellement la journée entière. Les horaires de préparation permettent de vérifier les trajets et les affectations.</p>'+(state.blocks.some(b=>!b.event_id)?panel('Indisponibilités',state.blocks.filter(b=>!b.event_id).map(b=>'<p>'+esc(b.label)+' · '+date(b.from_date)+' au '+date(b.to_date)+' <button class="text-button" data-unblock="'+esc(b.id)+'">Libérer ces dates</button></p>').join('')):'');}
function dossiers(){const match=q=>(q.name+' '+q.email+' '+q.company+' '+q.reference).toLowerCase().includes(search.toLowerCase());let rows=quotes().filter(match).filter(q=>filter==='all'||q.state===filter);return '<div class="toolbar"><input id="search" aria-label="Rechercher un client" placeholder="Nom, entreprise, e-mail…" value="'+esc(search)+'"><select id="dossier-filter" aria-label="État du dossier"><option value="all"'+(filter==='all'?' selected':'')+'>Tous les dossiers</option>'+[['open','Devis à suivre'],['paid','Réservés'],['closed','Relances arrêtées']].map(([v,t])=>'<option value="'+v+'"'+(filter===v?' selected':'')+'>'+t+'</option>').join('')+'</select><span class="muted">'+rows.length+' dossier(s)</span></div><section class="panel table-wrap"><table><thead><tr><th>CLIENT</th><th>ÉVÉNEMENT</th><th>DATE</th><th>DEVIS</th><th>ÉTAT / SUIVI</th></tr></thead><tbody>'+rows.map(q=>{const e=state.events.find(e=>e.quote_id===q.id);return '<tr><td><button class="table-link" data-event="'+esc(e?.id||'quote-'+q.id)+'"><b>'+esc(q.name)+'</b></button><small>'+esc(q.company||q.email)+'</small></td><td>'+esc(q.eventType)+'</td><td>'+date(q.date)+'</td><td>'+euro(q.totalCents)+'</td><td>'+badge(q.state)+(q.state==='open'?'<small>'+esc(stages[q.stage]||stages.new)+(q.nextActionDate?' · '+date(q.nextActionDate):'')+'</small>':'')+'</td></tr>';}).join('')+'</tbody></table>'+(!rows.length?empty('Aucun dossier correspondant.'):'')+'</section>'+panel('Événements externes',events().filter(e=>!e.booking_id).map(row).join('')||empty('Les événements ajoutés manuellement apparaîtront ici.'));}
function preparation(){const selected=state.tasks.filter(t=>events().some(e=>e.id===t.event_id)).filter(t=>taskFilter==='all'||taskFilter==='done'&&t.done||taskFilter==='open'&&!t.done||taskFilter==='today'&&t.due_date<=today());return '<div class="toolbar"><select id="task-filter" aria-label="Filtrer les tâches">'+[['open','À faire'],['today','Aujourd’hui et en retard'],['done','Terminées'],['all','Toutes les tâches']].map(([v,t])=>'<option value="'+v+'"'+(taskFilter===v?' selected':'')+'>'+t+'</option>').join('')+'</select><p class="muted">Les tâches terminées restent conservées.</p></div>'+panel('La préparation, simplement',selected.map(taskRow).join('')||empty('Aucune tâche dans cette vue.'));}
function resources(kind){const list=state.resources.filter(r=>r.kind===kind&&r.active);return '<div class="section-head"><p class="muted">Affectez vos '+(kind==='staff'?'baristas':'équipements')+' depuis la fiche de chaque événement.</p><button data-new-resource="'+kind+'">+ Ajouter</button></div><div class="card-grid">'+list.map(r=>'<article class="resource"><p class="eyebrow">'+(kind==='staff'?'ÉQUIPE':'MATÉRIEL')+'</p><h2>'+esc(r.name)+'</h2><span class="badge">'+r.quantity+' disponible(s)</span><p>'+esc(r.notes||'Aucune note particulière.')+'</p><small>'+state.assignments.filter(a=>a.resource_id===r.id&&a.ends_at>Date.now()).length+' affectation(s) à venir</small><br><button class="secondary" data-resource="'+esc(r.id)+'">Modifier</button></article>').join('')+'</div>';}
function settings(){const s=state.settings;return '<section class="panel"><label class="check-label"><input id="show-tests" type="checkbox" '+(showTests?'checked':'')+'>Afficher les dossiers de test et les essais</label><p class="subtle">Ils restent conservés et sont masqués par défaut pour garder votre espace clair.</p></section><form id="settings-form" class="settings-form">'+panel('Temps de préparation par défaut','<p class="muted">Ces durées servent de point de départ. Le trajet doit être vérifié pour chaque événement.</p><div class="form-grid">'+field('loadingMinutes','Chargement / déchargement, minutes',s.loadingMinutes,'number','min="0" max="2880" required')+field('setupMinutes','Installation, minutes',s.setupMinutes,'number','min="0" max="2880" required')+field('cleanupMinutes','Rangement, minutes',s.cleanupMinutes,'number','min="0" max="2880" required')+field('travelMinutes','Trajet aller, minutes',s.travelMinutes,'number','min="0" max="2880" required')+'</div>')+panel('Les avis après l’événement','<label class="check-label"><input type="checkbox" name="reviewEnabled" '+(s.reviewEnabled?'checked':'')+'>Activer les demandes d’avis</label><p class="muted">Les demandes partent automatiquement après les nouveaux événements. Vous pouvez suspendre un envoi depuis sa fiche. Les essais et les anciens événements sont exclus.</p>'+field('reviewUrl','Lien officiel pour laisser un avis Google',s.reviewUrl,'url','required')+field('reviewDelayDays','Nombre de jours après l’événement',s.reviewDelayDays,'number','min="1" max="30" required'))+panel('Visio avec les prospects','<p class="muted">Ce lien est envoyé dans chaque invitation en visio. Créez-le une fois sur meet.google.com : Nouvelle réunion, puis Créer une réunion pour plus tard.</p>'+field('meetUrl','Mon lien Google Meet',s.meetUrl||'','url','placeholder="https://meet.google.com/abc-defg-hij"'))+'<button>Enregistrer les réglages</button></form>' +panel('Vos données','<p>Les devis et les paiements restent dans leurs dossiers d’origine. Cet espace ajoute la préparation et le planning sans modifier les documents financiers.</p><button class="secondary" data-command="export">Exporter les données de l’espace</button>');}
const categoryNames={'cups-printed':'Gobelets imprimés','cups-plain':'Gobelets standards','stickers':'Stickers pour gobelets','bar-wrap':'Habillage du bar','foam':'Logo sur la mousse'};
const orderStatusNames={planning:'À préparer',ready:'Prêt à commander',ordered:'Commandé',received:'Reçu / prêt'};
const supplierHref=s=>{try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password?esc(u.href):'#';}catch{return '#';}};
function suppliers(){return '<div class="section-head"><p class="muted">Vos pistes et vos règles de commande, au même endroit.</p><button data-command="new-supplier">+ Ajouter un fournisseur</button></div><p class="subtle">Les fournisseurs retrouvés dans Notion sont des pistes à comparer. Les suggestions ne sont activées qu’après renseignement de vos conditions.</p><div class="card-grid">'+(state.suppliers||[]).map(s=>'<article class="resource"><p class="eyebrow">'+esc(categoryNames[s.category])+'</p><h2>'+esc(s.name)+'</h2><span class="badge '+(s.preferred?'':'open')+'">'+(s.preferred?'Suggestions activées':'À comparer')+'</span><p>'+esc(s.notes)+'</p><small>'+(s.min_quantity?'Minimum '+s.min_quantity+' · ':'')+(s.lead_days!==null?s.lead_days+' jours prévus':'Délai à préciser')+'</small><div class="supplier-actions">'+(s.url?'<a class="button" href="'+supplierHref(s.url)+'" target="_blank" rel="noopener noreferrer">Site fournisseur</a>':'<small>Lien à renseigner</small>')+'<button class="secondary" data-supplier="'+esc(s.id)+'">Configurer</button></div></article>').join('')+'</div>';}
function supplierForm(id){const s=(state.suppliers||[]).find(x=>x.id===id)||{priority:10,active:1,category:'cups-printed'};opened=null;showDialog(s.id?'Configurer '+s.name:'Ajouter un fournisseur','<form id="supplier-form" data-id="'+esc(s.id||'')+'">'+field('name','Nom',s.name||'','text','required maxlength="150"')+inputSelect('category','Produit',Object.entries(categoryNames),s.category)+field('url','Lien vers le produit ou le site',s.url||'','url')+'<div class="form-grid">'+field('minQuantity','Quantité minimum',s.min_quantity??'','number','min="1" max="1000000"')+field('maxQuantity','Quantité maximum',s.max_quantity??'','number','min="1" max="1000000"')+field('leadDays','Jours à prévoir avant l’événement',s.lead_days??'','number','min="0" max="180"')+field('priority','Priorité des suggestions (petit nombre en premier)',s.priority,'number','min="0" max="1000"')+'</div><p class="subtle">Prévoyez la fabrication, la livraison et votre marge de sécurité. Les délais annoncés sur les sites restent à confirmer.</p><div class="field"><label for="supplier-notes">Conditions et instructions</label><textarea id="supplier-notes" name="notes" maxlength="4000">'+esc(s.notes)+'</textarea></div><label class="check-label"><input name="preferred" type="checkbox" '+(s.preferred?'checked':'')+'>Autoriser les suggestions pour ce fournisseur</label><label class="check-label"><input name="active" type="checkbox" '+(s.active?'checked':'')+'>Fournisseur actif</label><button>Enregistrer le fournisseur</button></form>');}
function orderForm(o,e,list){const matches=list.filter(s=>(s.active||s.id===o.supplier_id)&&s.category===o.category),selected=list.find(s=>s.id===o.supplier_id),suggested=o.suggestions||[];return ('<details class="order-card"><summary><b>'+esc(categoryNames[o.category])+'</b><span class="badge '+(o.status==='received'?'completed':'open')+'">'+esc(orderStatusNames[o.status])+'</span></summary><form class="order-form" data-id="'+esc(o.id)+'" data-event="'+esc(e.id)+'" data-version="'+o.updated_at+'"><p class="subtle">'+esc(e.data.guests)+' invités : cela ne fixe pas automatiquement le nombre de gobelets ou de stickers à commander.</p><div class="form-grid">'+field('quantity','Quantité prévue',o.quantity??'','number','min="1" max="1000000"')+field('format','Format / contenance / dimensions',o.format||'','text','maxlength="250"')+'</div><label class="check-label"><input type="checkbox" name="quantityConfirmed" '+(o.quantity_confirmed?'checked':'')+'>Quantité confirmée pour cet événement</label><div class="field"><label for="request-'+esc(o.id)+'">Ce que souhaite exactement le client</label><textarea id="request-'+esc(o.id)+'" name="clientRequest" maxlength="4000" placeholder="Couleurs, texte, logo, emplacement, finition…">'+esc(o.client_request)+'</textarea></div>'+inputSelect('artworkStatus','État du visuel',[...(o.category==='cups-plain'?[['not-needed','Sans personnalisation']]:[]),['needed','À récupérer'],['received','Fichier reçu'],['review','À faire valider'],['approved','Visuel validé']],o.artwork_status)+field('artworkUrl','Lien vers le fichier ou le visuel validé',o.artwork_url||'','url')+inputSelect('supplierId','Fournisseur', [['','À choisir'],...matches.map(s=>[s.id,s.name+(suggested.some(x=>x.id===s.id)?' · suggéré':'')])],o.supplier_id||'')+(selected?.url?'<a class="button" href="'+supplierHref(selected.url)+'" target="_blank" rel="noopener noreferrer">Ouvrir le site de '+esc(selected.name)+'</a>':'')+'<p class="subtle">'+(suggested.length?'Suggestions selon vos règles : '+esc(suggested.map(s=>s.name).join(', '))+'.':!o.quantity_confirmed?'Confirmez la quantité puis enregistrez pour obtenir des suggestions.':'Aucun fournisseur activé ne correspond à cette quantité et au délai. Vous pouvez configurer vos règles dans Fournisseurs.')+'</p><div class="form-grid">'+inputSelect('status','Avancement',Object.entries(orderStatusNames),o.status)+field('dueDate','Date limite de commande',o.due_date||'','date')+'</div>'+field('orderReference','Référence de commande',o.order_reference||'','text','maxlength="200"')+field('orderUrl','Lien de suivi ou de commande',o.order_url||'','url')+'<div class="field"><label for="notes-'+esc(o.id)+'">Notes internes</label><textarea id="notes-'+esc(o.id)+'" name="notes" maxlength="4000">'+esc(o.notes)+'</textarea></div><button>Enregistrer ce suivi</button><p class="subtle">Ce suivi n’effectue aucun achat et ne modifie pas le prix du devis.</p></form></details>').replaceAll('id="f-','id="order-'+esc(o.id)+'-').replaceAll('for="f-','for="order-'+esc(o.id)+'-');}
const prospectStatus={'a-contacter':'À contacter',contacte:'Contacté',repondu:'A répondu',rdv:'Rendez-vous',devis:'Devis envoyé',gagne:'Client',perdu:'Sans suite'},prospectSource={linkedin:'LinkedIn',mail:'E-mail',telephone:'Téléphone',salon:'Salon ou événement',recommandation:'Recommandation',autre:'Autre'},prospectKind={linkedin:'Message LinkedIn',mail_out:'E-mail envoyé',mail_in:'E-mail reçu',call:'Appel',meeting:'Rendez-vous',note:'Note'};
const pBadge=s=>'<span class="badge p-'+esc(s)+'">'+esc(prospectStatus[s]||s)+'</span>';
const gmailCompose=to=>'https://mail.google.com/mail/?authuser=contact.eywa08@gmail.com&view=cm&fs=1&to='+encodeURIComponent(to);
const waLink=p=>{let n=String(p||'').replace(/[^\d+]/g,'');if(n.startsWith('0'))n='33'+n.slice(1);return 'https://wa.me/'+n.replace(/^\+/,'');};
function prospects(){const list=state.prospects||[],t=today(),match=p=>(p.name+' '+p.company+' '+p.role+' '+p.email).toLowerCase().includes(search.toLowerCase());const rows=list.filter(match).filter(p=>filter==='all'?p.status!=='perdu':filter==='due'?(p.next_action_date&&p.next_action_date<=t&&!['gagne','perdu'].includes(p.status)):p.status===filter);
const due=list.filter(p=>p.next_action_date&&p.next_action_date<=t&&!['gagne','perdu'].includes(p.status)).length;
const counts=Object.keys(prospectStatus).map(k=>[k,list.filter(p=>p.status===k).length]).filter(([,n])=>n);
return '<div class="section-head"><p class="muted">Toutes les personnes contactées, leurs échanges et vos prochaines relances.</p><button data-command="new-prospect">+ Ajouter un prospect</button></div>'+
'<div class="prospect-stats">'+(due?'<button class="stat due" data-view="prospects" data-filter="due"><b>'+due+'</b> à relancer</button>':'')+counts.map(([k,n])=>'<button class="stat" data-view="prospects" data-filter="'+k+'"><b>'+n+'</b> '+esc(prospectStatus[k])+'</button>').join('')+'</div>'+
'<div class="toolbar"><input id="search" aria-label="Rechercher un prospect" placeholder="Nom, entreprise, e-mail…" value="'+esc(search)+'"><select id="prospect-filter" aria-label="Statut"><option value="all"'+(filter==='all'?' selected':'')+'>En cours</option><option value="due"'+(filter==='due'?' selected':'')+'>À relancer</option>'+Object.entries(prospectStatus).map(([v,x])=>'<option value="'+v+'"'+(filter===v?' selected':'')+'>'+x+'</option>').join('')+'</select><span class="muted">'+rows.length+' prospect(s)</span></div>'+
'<section class="panel table-wrap"><table><thead><tr><th>PERSONNE</th><th>CANAL</th><th>STATUT</th><th>DERNIER ÉCHANGE</th><th>RELANCE</th></tr></thead><tbody>'+rows.map(p=>'<tr><td><button class="table-link" data-prospect="'+esc(p.id)+'"><b>'+esc(p.name)+'</b></button><small>'+esc([p.role,p.company].filter(Boolean).join(' · ')||p.email)+'</small></td><td>'+esc(prospectSource[p.source]||p.source)+'</td><td>'+pBadge(p.status)+'</td><td>'+(p.last_contact_at?dt(p.last_contact_at):'<small>Aucun</small>')+(p.exchanges?'<small>'+p.exchanges+' échange(s)</small>':'')+'</td><td>'+(p.next_action_date?'<span class="'+(p.next_action_date<=t&&!['gagne','perdu'].includes(p.status)?'late':'')+'">'+date(p.next_action_date)+'</span>':'<small>—</small>')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?empty(list.length?'Aucun prospect pour ce filtre.':'Ajoutez votre premier prospect : une personne contactée sur LinkedIn, par e-mail ou sur un salon.'):'')+'</section>';}
function prospectForm(id){const p=(state.prospects||[]).find(x=>x.id===id)||{source:'linkedin',status:'contacte'};showDialog(p.id?'Modifier '+p.name:'Ajouter un prospect','<form id="prospect-form" data-id="'+esc(p.id||'')+'"><div class="form-grid">'+field('name','Nom et prénom',p.name||'','text','required maxlength="150"')+field('company','Entreprise',p.company||'','text','maxlength="150"')+field('role','Poste',p.role||'','text','maxlength="150"')+field('email','E-mail',p.email||'','email','maxlength="254"')+field('phone','Téléphone',p.phone||'','tel','maxlength="40"')+field('linkedinUrl','Profil LinkedIn',p.linkedin_url||'','url','placeholder="https://www.linkedin.com/in/…"')+inputSelect('source','Contacté par',Object.entries(prospectSource),p.source)+inputSelect('status','Statut',Object.entries(prospectStatus),p.status)+field('nextActionDate','Prochaine relance',p.next_action_date||'','date')+'</div><div class="field"><label for="prospect-notes">Notes</label><textarea id="prospect-notes" name="notes" maxlength="4000">'+esc(p.notes||'')+'</textarea></div><p class="subtle">Avec une adresse e-mail, les messages échangés depuis la boîte EYWA apparaissent automatiquement dans l’historique (sous 30 minutes).</p><button>Enregistrer</button></form>');}
async function openProspect(id){opened=null;const p=await api('prospect?id='+encodeURIComponent(id));const links=[p.email?'<a class="button" href="'+esc(gmailCompose(p.email))+'" target="_blank" rel="noopener">Écrire un e-mail</a>':'',p.linkedin_url?'<a class="button secondary" href="'+esc(p.linkedin_url)+'" target="_blank" rel="noopener noreferrer">Profil LinkedIn</a>':'',p.phone?'<a class="button secondary" href="tel:'+esc(p.phone.replace(/[^\d+]/g,''))+'">Appeler</a>':'',p.phone?'<a class="button secondary" href="'+esc(waLink(p.phone))+'" target="_blank" rel="noopener noreferrer">WhatsApp</a>':''].join('');
showDialog(p.name,'<p class="eyebrow">'+esc([p.role,p.company].filter(Boolean).join(' · ')||'Prospect')+'</p><p>'+pBadge(p.status)+' <span class="muted">'+esc(prospectSource[p.source]||'')+(p.next_action_date?' · relance le '+date(p.next_action_date):'')+'</span></p><div class="client-request">'+(p.email?'<p>'+esc(p.email)+'</p>':'')+(p.phone?'<p>'+esc(p.phone)+'</p>':'')+(p.notes?'<p>'+esc(p.notes)+'</p>':'')+'</div><div class="prospect-actions">'+links+(p.email?'<button data-meet-prospect="'+esc(p.id)+'">Inviter en visio (Google Meet)</button>':'')+'<button class="secondary" data-edit-prospect="'+esc(p.id)+'">Modifier la fiche</button></div>'+
'<hr class="split-line"><h2>Noter un échange</h2><form id="prospect-log-form" data-id="'+esc(p.id)+'"><div class="form-grid">'+inputSelect('kind','Type',Object.entries(prospectKind).filter(([k])=>k!=='mail_in'),'linkedin')+field('date','Date',today(),'date','required')+field('nextActionDate','Prochaine relance (facultatif)','','date')+'</div><div class="field"><label for="log-summary">Ce qui s’est dit</label><textarea id="log-summary" name="summary" maxlength="2000" required placeholder="Ex. : message LinkedIn envoyé, elle répond la semaine prochaine"></textarea></div><button>Ajouter à l’historique</button></form>'+
'<hr class="split-line"><h2>Historique</h2>'+(p.events.length?'<div class="timeline">'+p.events.map(e=>'<div><b>'+esc(prospectKind[e.kind]||e.kind)+'</b> · <span>'+dt(e.at)+'</span><p>'+esc(e.summary)+'</p>'+(e.body?'<details><summary>Lire le message</summary><p class="mail-body">'+esc(e.body.slice(0,4000))+'</p></details>':'')+(e.id.startsWith('gmail:')?'':'<button class="text-button" data-delete-log="'+esc(e.id)+'">Supprimer</button>')+'</div>').join('')+'</div>':empty('Aucun échange pour l’instant.')));}
function render(){if(!state)return;$('#page-title').textContent=titles[view];document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('#notice').hidden=!state.limited;if(state.limited)$('#notice').textContent='Cette vue affiche les 1 500 dossiers les plus récents. Exportez vos données avant un archivage.';$('#content').innerHTML=({home,calendar,dossiers,tasks:preparation,staff:()=>resources('staff'),equipment:()=>resources('equipment'),suppliers,prospects,settings}[view])();}
function showDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=body;if(!$('#detail').open)$('#detail').showModal();}
function summary(q){return '<div class="detail-summary">'+[['Date',date(q.date)+' · '+(q.time||'')],['Invités / durée',(q.guests||'À préciser')+' invités · '+(q.hours||'À préciser')+' h par jour · '+(q.days||1)+' jour(s)'],['Lieu',q.location],['E-mail',q.email],['Téléphone',q.phone],['Type',q.eventType],['Entreprise',q.company||'Non renseignée']].map(([l,v])=>'<div><small>'+esc(l)+'</small><p>'+esc(v||'À préciser')+'</p></div>').join('')+'</div>';}
async function openEvent(id){opened=id;const e=await api('event?id='+encodeURIComponent(id)),q=e.data,t=q.timeline;if(e.calendarOnly){showDialog(q.name,'<p class="eyebrow">Google Agenda · Lecture seule</p><div class="client-request"><p><b>'+dt(e.starts_at)+' → '+dt(e.ends_at)+'</b></p><p>'+esc(q.location||'Lieu non renseigné')+'</p></div><p>'+esc(q.allDay?'Événement sur la journée.':'Horaire repris de votre agenda.')+'</p>'+(q.notes?'<h3>Notes dans votre agenda</h3><pre class="calendar-notes">'+esc(q.notes)+'</pre>':'')+'<p class="subtle">'+(q.transparent?'Marqué disponible dans Google : ne bloque pas les réservations.':'Ce rendez-vous bloque les journées concernées sur le site.')+' Les marges de préparation et de trajet restent à vérifier.</p><a class="button" href="https://calendar.google.com/" target="_blank" rel="noopener">Ouvrir Google Agenda</a><p class="subtle">Les modifications se font dans Google Agenda. Cet import ne crée ni facture ni message client.</p>');return;}let body=(e.quote_id?'<p class="eyebrow">'+esc(e.originalQuote?.reference||q.reference||'Devis EYWA')+' · '+euro(e.originalQuote?.totalCents??q.totalCents)+'</p>':'')+summary(q)+'<p>'+esc((q.options||[]).join(' · '))+'</p><div class="inline-actions">'+(e.quote_id?'<a class="button" href="'+safeLink(q.quoteUrl||'https://eywa-booking.eywa-booking-cloudflare.workers.dev/quote-view?id='+e.quote_id)+'" target="_blank" rel="noopener">Voir le devis</a><a class="button" href="/quote-pdf?id='+encodeURIComponent(e.quote_id)+'" target="_blank" rel="noopener">PDF du devis</a>':'')+'</div>';
if(e.clientMessage)body+='<div class="client-request"><small>Demande initiale du client</small><p>'+esc(e.clientMessage)+'</p></div>';
body+=correspondencePanel(e);
if(e.quoteOnly){body+='<p class="subtle">La demande de devis ne bloque pas la date.</p><button class="secondary" data-stop="'+esc(e.quote_id)+'">Arrêter les relances de ce devis</button>';}else{
body+='<hr class="split-line"><h2>Le déroulé</h2><div class="timeline"><span>'+dt(e.starts_at)+' · Début de préparation</span><span>'+dt(t.serviceStart)+' · Début du service</span><span>'+dt(t.serviceEnd)+' · Fin du service</span><span>'+dt(e.ends_at)+' · Retour et déchargement terminés</span></div><form id="event-form" data-id="'+esc(id)+'"><div class="form-grid">'+field('loadingMinutes','Chargement / déchargement, min',t.loadingMinutes,'number','min="0" max="2880" required')+field('setupMinutes','Installation, min',t.setupMinutes,'number','min="0" max="2880" required')+field('cleanupMinutes','Rangement, min',t.cleanupMinutes,'number','min="0" max="2880" required')+field('travelMinutes','Trajet aller réel, min',t.travelMinutes,'number','min="0" max="2880" required')+'</div><p class="subtle">Trajet estimé à vérifier. Le même temps est prévu pour le retour. La disponibilité publique reste bloquée à la journée.</p>'+inputSelect('status','État de l’événement',[['confirmed','Réservé'],['completed','Terminé'],...(!e.booking_id?[['cancelled','Annulé']]:[])],e.status)+'<div class="field"><label for="event-notes">Notes de préparation</label><textarea name="notes" id="event-notes" maxlength="10000">'+esc(q.notes)+'</textarea></div><button>Enregistrer la préparation</button></form>';
body+='<hr class="split-line"><h2>Commandes et personnalisations</h2>'+(e.clientMessage?'<div class="client-request"><small>Demande initiale du client</small><p>'+esc(e.clientMessage)+'</p></div>':'')+(e.referencePhoto?'<details><summary>Photo de référence du client</summary><img class="reference-photo" src="'+esc(e.referencePhoto)+'" alt="Photo de référence envoyée par le client"></details>':'')+(e.procurement?.orders||[]).map(o=>orderForm(o,e,e.procurement.suppliers)).join('');
const details=q.bookingDetails||{};body+='<hr class="split-line"><h2>Sur place</h2>'+Object.entries({Contact:details.contactName,Installation:details.setupLocation,Déchargement:details.unloadParking,Parking:details.eventParking,Tenue:details.dressCode,Précisions:details.dressDetails}).filter(([,v])=>v).map(([k,v])=>'<p><small>'+esc(k)+'</small><br>'+esc(v)+'</p>').join('');
body+='<hr class="split-line"><h2>La préparation</h2>'+state.tasks.filter(task=>task.event_id===id).map(taskRow).join('')+'<form id="task-form" data-id="'+esc(id)+'"><div class="form-grid">'+field('title','Nouvelle tâche','','text','required maxlength="250"')+field('dueDate','Échéance',q.date,'date','required')+'</div><button class="secondary">Ajouter la tâche</button></form><hr class="split-line"><h2>Baristas et matériel</h2><p class="muted">'+esc(q.staff||Math.max(1,Math.ceil(q.guests/(q.hours*50))))+' barista(s) à prévoir pour ce service.</p>';
body+=state.assignments.filter(a=>a.event_id===id).map(a=>'<p>'+esc(state.resources.find(r=>r.id===a.resource_id)?.name||a.resource_id)+' × '+a.quantity+' <button class="text-button" data-unassign="'+esc(a.resource_id)+'">Retirer</button></p>').join('');
body+='<form id="assignment-form" data-id="'+esc(id)+'"><div class="resource-assignment"><select name="resourceId" aria-label="Barista ou matériel">'+state.resources.filter(r=>r.active).map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+' ('+(r.kind==='staff'?'barista':'matériel')+')</option>').join('')+'</select><input type="number" name="quantity" min="1" max="100" value="1" aria-label="Quantité" required><button>Affecter</button></div></form><hr class="split-line"><h2>Avis après l’événement</h2><p class="muted">'+(e.review_state==='sent'?'Demande d’avis envoyée.':e.review_state==='queued'?'Demande d’avis en attente d’envoi.':!e.review_eligible?'Ancien événement : aucun envoi automatique.':'L’envoi est prévu après la fin de l’événement, si les demandes d’avis sont activées.')+'</p>'+(e.review_eligible&&e.review_state!=='sent'?'<label class="check-label"><input type="checkbox" data-review="'+esc(id)+'" '+(['ready','queued'].includes(e.review_state)?'checked':'')+'>Autoriser la demande d’avis pour cet événement</label>':'');
}
body+='<hr class="split-line"><h2>Factures</h2>'+(e.invoices.map(i=>'<a class="button" href="/invoice?token='+encodeURIComponent(i.token)+'&format=pdf" target="_blank" rel="noopener">'+esc(i.data.kind==='balance'?'Facture de solde':'Facture')+' · '+euro(i.data.kind==='balance'?i.data.balanceCents:i.data.paidCents)+'</a>').join('')||'<p class="muted">Aucune facture émise.</p>')+'<hr class="split-line"><h2>Les échanges</h2>'+(e.messages.map(m=>'<details class="message"><summary>'+esc(m.subject||m.title||'Message')+'<small> · '+dt(m.at)+' · '+esc(({sent:'envoyé',pending:'en attente',received:'reçu',sending:'en cours',archived:'archivé'})[m.status]||m.status)+'</small></summary><pre>'+esc(m.text)+'</pre></details>').join('')||'<p class="muted">Aucun échange enregistré.</p>');showDialog(q.name||'Dossier événement',body);}
function newEvent(){opened=null;showDialog('Ajouter un événement externe','<p class="muted">Pour une réservation reçue ailleurs. Cela bloque le calendrier et crée la préparation, sans créer de paiement ni de facture.</p><form id="manual-event-form"><div class="form-grid">'+field('name','Client','','text','required maxlength="150"')+field('company','Entreprise')+field('email','E-mail','','email')+field('phone','Téléphone','','tel')+field('date','Date','','date','required')+field('time','Début du service','10:00','time','required')+field('hours','Heures de service',1.5,'number','min="0.5" max="24" step="0.5" required')+field('days','Nombre de jours',1,'number','min="1" max="365" required')+field('guests','Invités',50,'number','min="0" max="100000" required')+field('eventType','Type d’événement','Événement privé')+'<div class="wide">'+field('location','Adresse')+'</div></div><button>Créer l’événement</button></form>');}
function resourceForm(kind,id){const r=state.resources.find(r=>r.id===id)||{kind,quantity:1,active:1};showDialog(r.id?'Modifier '+r.name:'Ajouter '+(kind==='staff'?'un barista':'du matériel'),'<form id="resource-form" data-id="'+esc(r.id||'')+'" data-kind="'+esc(r.kind)+'">'+field('name','Nom',r.name||'','text','required maxlength="100"')+field('quantity','Quantité disponible',r.quantity,'number','min="1" max="100" required')+'<div class="field"><label for="resource-notes">Notes</label><textarea id="resource-notes" name="notes" maxlength="1000">'+esc(r.notes)+'</textarea></div><label class="check-label"><input type="checkbox" name="active" '+(r.active?'checked':'')+'>Ressource active</label><button>Enregistrer</button></form>');}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{
if(b.dataset.view){view=b.dataset.view;search='';filter=b.dataset.filter||'all';render();}
if(b.dataset.event)await openEvent(b.dataset.event);
if(b.dataset.sendDraft){const f=$('#mail-draft-form');if(f?.dataset.dirty==='true')throw Error('Enregistrez vos modifications et relisez l’aperçu avant l’envoi.');if(confirm('Envoyer ce message à '+b.dataset.recipient+' ?')){b.disabled=true;try{const r=await api('action',{action:'mail-send',id:b.dataset.sendDraft,version:Number(b.dataset.version)});await load();await openEvent(opened);toast(r.status==='sent'?'Message envoyé.':'Message enregistré pour envoi. Le système réessaiera si nécessaire.');}finally{b.disabled=false;}}}
if(b.dataset.month){const n=Number(b.dataset.month),d=n?new Date(year,month+n,1):new Date();year=d.getFullYear();month=d.getMonth();render();}
if(b.dataset.supplier)supplierForm(b.dataset.supplier);
if(b.dataset.prospect)await openProspect(b.dataset.prospect);
if(b.dataset.command==='new-prospect')prospectForm();
if(b.dataset.editProspect)prospectForm(b.dataset.editProspect);
if(b.dataset.meetProspect){const p=(state.prospects||[]).find(x=>x.id===b.dataset.meetProspect);showDialog('Inviter '+(p?.name||'')+' en visio','<form id="meet-form" data-id="'+esc(b.dataset.meetProspect)+'"><p class="subtle">'+(state.settings.meetUrl?'L’invitation part de la boîte EYWA vers '+esc(p?.email||'')+', avec ton lien Google Meet et le rendez-vous à ajouter à son agenda. Tu reçois une copie. Le partage d’écran est possible pendant l’appel.':'<b>Ajoute d’abord ton lien Google Meet dans Réglages.</b>')+'</p><div class="form-grid">'+field('date','Date','','date','required min="'+today()+'"')+field('time','Heure','','time','required step="900"')+inputSelect('minutes','Durée',[[15,'15 min'],[30,'30 min'],[45,'45 min'],[60,'1 h'],[90,'1 h 30']],30)+'</div>'+field('title','Objet','Échange avec EYWA'+(p?.company?' · '+p.company:''),'text','maxlength="200"')+'<div class="field"><label for="meet-message">Message dans l’invitation (facultatif)</label><textarea id="meet-message" name="message" maxlength="3000"></textarea></div><button>Envoyer l’invitation</button></form>');}
if(b.dataset.deleteLog&&confirm('Supprimer cet échange de l’historique ?')){const r=await api('action',{action:'prospect-log-delete',id:b.dataset.deleteLog});await load();await openProspect(r.id);toast('Échange supprimé.');}
if(b.dataset.command==='calendar-refresh'){b.disabled=true;try{await act({action:'calendar-refresh'});}finally{b.disabled=false;}}
if(b.dataset.command==='new-supplier')supplierForm();
if(b.dataset.command==='quick-access')showDialog('Retrouver votre espace rapidement','<p><b>Sur ordinateur</b><br>Ajoutez cette page à vos favoris avec ⌘ D sur Mac, ou Ctrl D sur Windows.</p><p><b>Sur iPhone</b><br>Ouvrez l’espace dans Safari, puis Partager → Sur l’écran d’accueil.</p><p><b>Sur Android</b><br>Dans le menu du navigateur, choisissez Ajouter à l’écran d’accueil ou Installer.</p><p class="subtle">Votre connexion reste privée. Internet est nécessaire pour consulter les dossiers.</p>');
if(b.dataset.resource)resourceForm('',b.dataset.resource);
if(b.dataset.newResource)resourceForm(b.dataset.newResource);
if(b.dataset.unassign)await act({action:'assign',eventId:opened,resourceId:b.dataset.unassign,quantity:0},opened);
if(b.dataset.unblock&&confirm('Libérer ces dates pour de nouvelles réservations ?'))await act({action:'unblock',id:b.dataset.unblock});
if(b.dataset.stop&&confirm('Arrêter les relances de ce devis ?'))await act({action:'stop-followups',id:b.dataset.stop},opened);
if(b.dataset.command==='block'){opened=null;showDialog('Bloquer des dates','<form id="block-form">'+field('label','Motif','','text','required maxlength="150"')+field('from','Du',today(),'date','required')+field('to','Au',today(),'date','required')+'<button>Bloquer ces dates</button></form>');}
if(b.dataset.command==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EYWA-espace-'+today()+'.json';a.click();URL.revokeObjectURL(url);}
}catch(e){toast(e.message);}});
document.addEventListener('change',async ev=>{const x=ev.target;try{if(x.id==='show-tests'){showTests=x.checked;render();}if(x.id==='dossier-filter'){filter=x.value;render();}if(x.id==='task-filter'){taskFilter=x.value;render();}if(x.id==='prospect-filter'){filter=x.value;render();}if(x.dataset.task)await act({action:'task',id:x.dataset.task,done:x.checked},$('#detail').open?opened:null);if(x.dataset.review)await act({action:'review',id:x.dataset.review,enabled:x.checked},opened);}catch(e){if(x.type==='checkbox')x.checked=!x.checked;toast(e.message);}});
document.addEventListener('input',ev=>{if(ev.target.closest('#mail-draft-form')){const f=$('#mail-draft-form');f.dataset.dirty='true';const send=f.querySelector('[data-send-draft]');if(send)send.disabled=true;}if(ev.target.id==='search'){search=ev.target.value;const start=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(start,start);}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(f.id==='code-form')return;ev.preventDefault();const b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{
if(f.id==='quote-tracking-form')await act({action:'quote-tracking',...b,quoteId:f.dataset.quote,version:Number(f.dataset.version)},opened);
if(f.id==='mail-draft-form')await act({action:'mail-draft',...b,quoteId:f.dataset.quote,id:f.dataset.id||undefined,version:Number(f.dataset.version)},opened);
if(f.id==='event-form')await act({action:'event',id:f.dataset.id,notes:b.notes,status:b.status,timeline:Object.fromEntries(['loadingMinutes','setupMinutes','cleanupMinutes','travelMinutes'].map(k=>[k,Number(b[k])]))},f.dataset.id);
if(f.id==='task-form')await act({action:'add-task',eventId:f.dataset.id,...b},f.dataset.id);
if(f.id==='assignment-form')await act({action:'assign',eventId:f.dataset.id,resourceId:b.resourceId,quantity:Number(b.quantity)},f.dataset.id);
if(f.id==='manual-event-form'){const r=await api('action',{action:'manual-event',...b});await load();await openEvent(r.id);toast('Événement ajouté.');}
if(f.id==='prospect-form'){const r=await api('action',{action:'prospect',...b,id:f.dataset.id||undefined});await load();await openProspect(r.id);toast('Fiche enregistrée.');}
if(f.id==='meet-form'){if(!confirm('Envoyer l’invitation Google Meet maintenant ?'))return;const r=await api('action',{action:'prospect-meeting',...b,minutes:Number(b.minutes),prospectId:f.dataset.id});await load();await openProspect(f.dataset.id);toast(r.sent?'Invitation envoyée. Une copie est dans ta boîte EYWA.':'Invitation enregistrée, l’envoi sera réessayé automatiquement.');}
if(f.id==='prospect-log-form'){await api('action',{action:'prospect-log',...b,prospectId:f.dataset.id});await load();await openProspect(f.dataset.id);toast('Échange ajouté.');}
if(f.id==='supplier-form'){await act({action:'supplier',...b,id:f.dataset.id,preferred:new FormData(f).has('preferred'),active:new FormData(f).has('active')});$('#detail').close();}
if(f.classList.contains('order-form'))await act({action:'order',...b,id:f.dataset.id,updatedAt:Number(f.dataset.version),quantityConfirmed:new FormData(f).has('quantityConfirmed')},f.dataset.event);
if(f.id==='resource-form'){await act({action:'resource',...b,id:f.dataset.id,kind:f.dataset.kind,quantity:Number(b.quantity),active:new FormData(f).has('active')});$('#detail').close();}
if(f.id==='block-form'){await act({action:'block',...b});$('#detail').close();}
if(f.id==='settings-form')await act({action:'settings',...b,reviewEnabled:new FormData(f).has('reviewEnabled')});
}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}});
$('#request-code').addEventListener('click',async()=>{const b=$('#request-code');b.disabled=true;try{const r=await api('login',{});challenge=r.challenge;$('#code-form').hidden=false;$('#login-message').textContent=r.message;b.textContent='Renvoyer un code';$('#code').focus();}catch(e){$('#login-message').textContent=e.message;}finally{b.disabled=false;}});
$('#code-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('#code-form button');b.disabled=true;try{const r=await api('verify',{challenge,code:$('#code').value.trim()});csrf=r.csrf;$('#code').value='';await load();const s=await api('session');passkeySetup(s.passkeys);if(!$('#passkey-setup').hidden)toast('Activez Touch ID pour ne plus saisir de code : bouton en bas du menu.');}catch(e){$('#login-message').textContent=e.message;}finally{b.disabled=false;}});
$('#close-dialog').addEventListener('click',()=>$('#detail').close());$('#new-event').addEventListener('click',newEvent);$('#refresh').addEventListener('click',()=>load().catch(e=>toast(e.message)));$('#logout').addEventListener('click',async()=>{try{await api('logout',{});loginView();}catch(e){toast(e.message);}});
api('session').then(s=>{csrf=s.csrf;passkeySetup(s.passkeys);return load();}).catch(e=>{loginView();if(!/Connectez-vous/.test(e.message))$('#login-message').textContent=e.message;});

/* Connexion par empreinte (clé d'accès). Le code par e-mail reste disponible en secours. */
const b64u={enc:b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''),dec:s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'==='.slice((s.length+3)%4)),c=>c.charCodeAt(0))};
const passkeySupported=()=>!!(window.PublicKeyCredential&&navigator.credentials);
const deviceHasPasskey=()=>{try{return localStorage.getItem('eywa-passkey')==='1';}catch{return false;}};
function passkeySetup(count){$('#passkey-setup').hidden=!passkeySupported()||deviceHasPasskey();}
if(passkeySupported())$('#passkey-login').hidden=false;
$('#passkey-login').addEventListener('click',async()=>{const b=$('#passkey-login');b.disabled=true;$('#login-message').textContent='';try{
 const o=await api('passkey-login-options',{});
 const cred=await navigator.credentials.get({publicKey:{challenge:b64u.dec(o.challenge),rpId:o.rpId,timeout:o.timeout,userVerification:o.userVerification,allowCredentials:o.allowCredentials.map(c=>({type:c.type,id:b64u.dec(c.id)}))}});
 const r=cred.response,res=await api('passkey-login',{id:b64u.enc(cred.rawId),clientDataJSON:b64u.enc(r.clientDataJSON),authenticatorData:b64u.enc(r.authenticatorData),signature:b64u.enc(r.signature)});
 csrf=res.csrf;try{localStorage.setItem('eywa-passkey','1');}catch{}await load();passkeySetup();
}catch(e){$('#login-message').textContent=e.name==='NotAllowedError'?'Connexion annulée. Réessayez ou recevez un code.':e.message;}finally{b.disabled=false;}});
$('#passkey-setup').addEventListener('click',async()=>{const b=$('#passkey-setup');b.disabled=true;try{
 const o=await api('passkey-register-options',{});
 const cred=await navigator.credentials.create({publicKey:{...o,challenge:b64u.dec(o.challenge),user:{...o.user,id:b64u.dec(o.user.id)},excludeCredentials:o.excludeCredentials.map(c=>({type:c.type,id:b64u.dec(c.id)}))}});
 const r=cred.response;if(!r.getPublicKey||!r.getAuthenticatorData)throw Error('Ce navigateur ne permet pas encore Touch ID. Mettez-le à jour.');
 await api('passkey-register',{id:b64u.enc(cred.rawId),alg:r.getPublicKeyAlgorithm(),publicKey:b64u.enc(r.getPublicKey()),clientDataJSON:b64u.enc(r.clientDataJSON),authenticatorData:b64u.enc(r.getAuthenticatorData()),label:navigator.platform||''});
 try{localStorage.setItem('eywa-passkey','1');}catch{}b.hidden=true;toast('Touch ID est activé. La prochaine fois, posez simplement votre doigt.');
}catch(e){toast(e.name==='NotAllowedError'?'Activation annulée.':e.name==='InvalidStateError'?'Touch ID est déjà activé sur cet appareil.':e.message);if(e.name==='InvalidStateError'){try{localStorage.setItem('eywa-passkey','1');}catch{}b.hidden=true;}}finally{b.disabled=false;}});
})();
